export interface DialogController {
  open(): void;
  close(value?: string): void;
  destroy(): void;
}

export function createDialog(root: Element): DialogController {
  const dialog = root.querySelector<HTMLDialogElement>('[data-dialog]');
  const openButton = root.querySelector<HTMLButtonElement>('[data-dialog-open]');

  if (!dialog || !openButton) {
    throw new Error('Dialog markup is incomplete.');
  }

  let returnFocus: HTMLElement | null = null;

  const open = (): void => {
    returnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    dialog.showModal();
    root.dispatchEvent(new CustomEvent('dialog:open'));
  };

  const close = (value = ''): void => {
    if (dialog.open) dialog.close(value);
  };

  const handleBackdrop = (event: MouseEvent): void => {
    if (event.target === dialog) close('backdrop');
  };

  const handleClose = (): void => {
    returnFocus?.focus();
    root.dispatchEvent(new CustomEvent('dialog:close', {
      detail: { value: dialog.returnValue }
    }));
  };

  openButton.addEventListener('click', open);
  dialog.addEventListener('click', handleBackdrop);
  dialog.addEventListener('close', handleClose);

  return {
    open,
    close,
    destroy(): void {
      openButton.removeEventListener('click', open);
      dialog.removeEventListener('click', handleBackdrop);
      dialog.removeEventListener('close', handleClose);
    }
  };
}

document.querySelectorAll<HTMLElement>('[data-component="dialog"]').forEach(createDialog);

