.c-dialog-demo {
  --dialog-accent: #b9f474;
  --dialog-accent-text: #162600;
  --dialog-backdrop: rgb(20 24 18 / 55%);
  --dialog-border: #dcddd4;
  --dialog-border-strong: #bfc1b7;
  --dialog-canvas: #f5f5ef;
  --dialog-control-height: 2.75rem;
  --dialog-control-radius: 0.55rem;
  --dialog-focus: #b9f474;
  --dialog-font: Inter, ui-sans-serif, system-ui, sans-serif;
  --dialog-gutter: 1rem;
  --dialog-muted: #62665d;
  --dialog-radius: 1rem;
  --dialog-shadow: 0 1.5rem 5rem rgb(20 24 18 / 22%);
  --dialog-surface: #ffffff;
  --dialog-text: #171915;

  align-items: center;
  display: grid;
  font-family: var(--dialog-font);
  justify-items: center;
  min-height: 100%;
  padding: 2rem;
