  font-size: clamp(1.55rem, 5vw, 2rem);
  letter-spacing: -0.04em;
  line-height: 1.05;
  margin: 0.5rem 0 0;
}

.c-dialog__body {
  color: var(--dialog-muted);
  line-height: 1.6;
  margin: 0;
  padding: 0 1.5rem 1.5rem;
}

.c-dialog__actions {
  border-top: 1px solid var(--dialog-border);
  display: flex;
  gap: 0.75rem;
  justify-content: flex-end;
  padding: 1rem 1.5rem;
}

.c-button {
  background: transparent;
  border: 1px solid var(--dialog-border-strong);
  border-radius: var(--dialog-control-radius);
  color: inherit;
  cursor: pointer;
  font: inherit;
  font-weight: 650;
  min-height: var(--dialog-control-height);
  padding: 0.75rem 1rem;
}

.c-button:hover {
  border-color: currentColor;
}

.c-button:focus-visible {
  outline: 0.2rem solid var(--dialog-focus);
  outline-offset: 0.15rem;
}

.c-button--primary {
  background: var(--dialog-accent);
  border-color: var(--dialog-accent);
  color: var(--dialog-accent-text);
}

@media (max-width: 32rem) {
  .c-dialog__actions {
