export function createMaxDialog(root) {
  const dialog = root.querySelector('[data-dialog]');
  const openButton = root.querySelector('[data-dialog-open]');
  const closeButton = root.querySelector('[data-dialog-close]');
  const maximizeButton = root.querySelector('[data-dialog-maximize]');
  if (!(dialog instanceof HTMLDialogElement) || !(openButton instanceof HTMLButtonElement) || !(closeButton instanceof HTMLButtonElement) || !(maximizeButton instanceof HTMLButtonElement)) throw new Error('Maximizable dialog markup is incomplete.');
  const open = () => dialog.showModal();
  const close = () => dialog.close();
  const toggleMaximize = () => {
    const maximized = dialog.classList.toggle('c-dialog--maximized');
    maximizeButton.setAttribute('aria-pressed', String(maximized));
    maximizeButton.setAttribute('aria-label', maximized ? 'Restore dialog' : 'Maximize dialog');
    maximizeButton.textContent = maximized ? '❐' : '□';
  };
  const reset = () => { dialog.classList.remove('c-dialog--maximized'); maximizeButton.setAttribute('aria-pressed', 'false'); maximizeButton.setAttribute('aria-label', 'Maximize dialog'); maximizeButton.textContent = '□'; openButton.focus(); };
  openButton.addEventListener('click', open); closeButton.addEventListener('click', close); maximizeButton.addEventListener('click', toggleMaximize); dialog.addEventListener('close', reset);
  return { destroy() { openButton.removeEventListener('click', open); closeButton.removeEventListener('click', close); maximizeButton.removeEventListener('click', toggleMaximize); dialog.removeEventListener('close', reset); } };
}

document.querySelectorAll('[data-component="max-dialog"]').forEach(createMaxDialog);

