export function createAnimatedDialog(root) {
  const dialog = root.querySelector('[data-dialog]');
  const triggers = [...root.querySelectorAll('[data-dialog-animation]')];
  const closeButtons = [...root.querySelectorAll('[data-dialog-close]')];
  if (!(dialog instanceof HTMLDialogElement) || !triggers.length || !closeButtons.length) throw new Error('Animated dialog markup is incomplete.');

  let returnFocus = null;
  let closeTimer = 0;
  const open = (event) => {
    const trigger = event.currentTarget;
    if (!(trigger instanceof HTMLButtonElement)) return;
    dialog.dataset.animation = trigger.dataset.dialogAnimation || 'fade-scale';
    returnFocus = trigger;
    dialog.showModal();
    requestAnimationFrame(() => dialog.classList.add('is-opening'));
  };
  const finishClose = () => {
    window.clearTimeout(closeTimer);
    dialog.close();
  };
  const close = () => {
    if (!dialog.open || dialog.classList.contains('is-closing')) return;
    dialog.classList.remove('is-opening');
    dialog.classList.add('is-closing');
    closeTimer = window.setTimeout(finishClose, 220);
  };
  const handleAnimationEnd = (event) => {
    if (event.animationName === 'dialog-enter') dialog.classList.remove('is-opening');
    if (event.animationName === 'dialog-exit') finishClose();
  };
  const handleCancel = (event) => { event.preventDefault(); close(); };
  const handleBackdrop = (event) => { if (event.target === dialog) close(); };
  const restoreFocus = () => { dialog.classList.remove('is-opening', 'is-closing'); returnFocus?.focus(); };

  triggers.forEach((trigger) => trigger.addEventListener('click', open));
  closeButtons.forEach((button) => button.addEventListener('click', close));
  dialog.addEventListener('animationend', handleAnimationEnd);
  dialog.addEventListener('cancel', handleCancel);
  dialog.addEventListener('click', handleBackdrop);
  dialog.addEventListener('close', restoreFocus);

  return { destroy() {
    window.clearTimeout(closeTimer);
    triggers.forEach((trigger) => trigger.removeEventListener('click', open));
    closeButtons.forEach((button) => button.removeEventListener('click', close));
    dialog.removeEventListener('animationend', handleAnimationEnd);
    dialog.removeEventListener('cancel', handleCancel);
    dialog.removeEventListener('click', handleBackdrop);
    dialog.removeEventListener('close', restoreFocus);
